     1→"use client";
     2→
     3→import {
     4→	type CollisionDetection,
     5→	closestCenter,
     6→	DndContext,
     7→	type DragEndEvent,
     8→	type DragOverEvent,
     9→	DragOverlay,
    10→	type DragStartEvent,
    11→	defaultDropAnimation,
    12→	KeyboardSensor,
    13→	PointerSensor,
    14→	pointerWithin,
    15→	useSensor,
    16→	useSensors,
    17→} from "@dnd-kit/core";
    18→import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
    19→import { CSS } from "@dnd-kit/utilities";
    20→import type { Question, Survey } from "@orksys-survey/db";
    21→import { useMutation, useQueryClient } from "@tanstack/react-query";
    22→import {
    23→	ClipboardList,
    24→	GripVertical,
    25→	PanelLeftClose,
    26→	PanelRightClose,
    27→} from "lucide-react";
    28→import { createContext, useContext, useEffect, useState } from "react";
    29→import { toast } from "sonner";
    30→
    31→import { Button } from "@/components/ui/button";
    32→import { Card, CardContent } from "@/components/ui/card";
    33→import { Sheet, SheetContent } from "@/components/ui/sheet";
    34→import { useMediaQuery } from "@/hooks/use-media-query";
    35→import { cn } from "@/lib/utils";
    36→import { orpc } from "@/utils/orpc";
    37→import { BuilderCanvas } from "./builder-canvas";
    38→import { BuilderHeader } from "./builder-header";
    39→import { PropertiesPanel } from "./properties-panel";
    40→import { QuestionPalette } from "./question-palette";
    41→
    42→// Question type configs for drag overlay
    43→const questionTypeIcons: Record<string, React.ElementType> = {
    44→	text: ClipboardList,
    45→	textarea: ClipboardList,
    46→	multiple_choice: ClipboardList,
    47→	checkbox: ClipboardList,
    48→	dropdown: ClipboardList,
    49→	rating: ClipboardList,
    50→	nps: ClipboardList,
    51→	linear_scale: ClipboardList,
    52→	date: ClipboardList,
    53→	email: ClipboardList,
    54→	phone: ClipboardList,
    55→	file_upload: ClipboardList,
    56→};
    57→
    58→const questionTypeLabels: Record<string, string> = {
    59→	text: "Short Text",
    60→	textarea: "Long Text",
    61→	multiple_choice: "Multiple Choice",
    62→	checkbox: "Checkboxes",
    63→	dropdown: "Dropdown",
    64→	rating: "Rating",
    65→	nps: "NPS",
    66→	linear_scale: "Linear Scale",
    67→	date: "Date",
    68→	email: "Email",
    69→	phone: "Phone",
    70→	file_upload: "File Upload",
    71→};
    72→
    73→// Builder context for sharing state across components
    74→interface SurveyBuilderContextValue {
    75→	survey: Survey;
    76→	questions: Question[];
    77→	selectedQuestionId: string | null;
    78→	setSelectedQuestionId: (id: string | null) => void;
    79→	activeTab: "build" | "preview";
    80→	setActiveTab: (tab: "build" | "preview") => void;
    81→	onQuestionsChange: (questions: Question[]) => void;
    82→	paletteOpen: boolean;
    83→	setPaletteOpen: (open: boolean) => void;
    84→	propertiesOpen: boolean;
    85→	setPropertiesOpen: (open: boolean) => void;
    86→}
    87→
    88→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
    89→	null,
    90→);
    91→
    92→export function useSurveyBuilder() {
    93→	const context = useContext(SurveyBuilderContext);
    94→	if (!context) {
    95→		throw new Error(
    96→			"useSurveyBuilder must be used within a SurveyBuilder component",
    97→		);
    98→	}
    99→	return context;
   100→}
   101→
   102→// Drag item types
   103→interface PaletteDragItem {
   104→	type: "palette";
   105→	questionType: Question["type"];
   106→}
   107→
   108→interface QuestionDragItem {
   109→	type: "question";
   110→	id: string;
   111→}
   112→
   113→type DragItem = PaletteDragItem | QuestionDragItem;
   114→
   115→interface SurveyBuilderProps {
   116→	survey: Survey;
   117→	questions: Question[];
   118→	className?: string;
   119→}
   120→
   121→export function SurveyBuilder({
   122→	survey,
   123→	questions: initialQuestions,
   124→	className,
   125→}: SurveyBuilderProps) {
   126→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   127→		null,
   128→	);
   129→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   130→	const [questions, setQuestions] = useState(initialQuestions);
   131→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   132→	const [paletteOpen, setPaletteOpen] = useState(false);
   133→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   134→
   135→	// Responsive breakpoints
   136→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   137→
   138→	const queryClient = useQueryClient();
   139→
   140→	// Sync state when initialQuestions changes
   141→	useEffect(() => {
   142→		setQuestions(initialQuestions);
   143→	}, [initialQuestions]);
   144→
   145→	// Create question mutation (for palette drops)
   146→	const createMutation = useMutation(
   147→		orpc.question.create.mutationOptions({
   148→			onSuccess: (newQuestion) => {
   149→				setQuestions((prev) => [...prev, newQuestion]);
   150→				setSelectedQuestionId(newQuestion.id);
   151→				queryClient.invalidateQueries({ queryKey: ["question"] });
   152→				toast.success("Question added");
   153→			},
   154→			onError: (error) => {
   155→				toast.error(error.message || "Failed to create question");
   156→			},
   157→		}),
   158→	);
   159→
   160→	// Reorder mutation
   161→	const reorderMutation = useMutation(
   162→		orpc.question.reorder.mutationOptions({
   163→			onSuccess: () => {
   164→				queryClient.invalidateQueries({ queryKey: ["question"] });
   165→			},
   166→			onError: (error) => {
   167→				toast.error(error.message || "Failed to reorder questions");
   168→			},
   169→		}),
   170→	);
   171→
   172→	// DnD sensors
   173→	const sensors = useSensors(
   174→		useSensor(PointerSensor, {
   175→			activationConstraint: {
   176→				distance: 5,
   177→			},
   178→		}),
   179→		useSensor(KeyboardSensor, {
   180→			coordinateGetter: sortableKeyboardCoordinates,
   181→		}),
   182→	);
   183→
   184→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   185→	const collisionDetection: CollisionDetection = (args) => {
   186→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   187→		if (args.active.data.current?.questionType) {
   188→			const pointerCollisions = pointerWithin(args);
   189→			if (pointerCollisions.length > 0) {
   190→				return pointerCollisions;
   191→			}
   192→		}
   193→		// For canvas reordering, use closestCenter for better sortable behavior
   194→		return closestCenter(args);
   195→	};
   196→
   197→	const handleDragStart = (event: DragStartEvent) => {
   198→		const { active } = event;
   199→		const data = active.data.current;
   200→
   201→		if (data?.questionType) {
   202→			// Dragging from palette
   203→			setActiveDragItem({
   204→				type: "palette",
   205→				questionType: data.questionType as Question["type"],
   206→			});
   207→		} else {
   208→			// Dragging existing question
   209→			setActiveDragItem({
   210→				type: "question",
   211→				id: active.id as string,
   212→			});
   213→		}
   214→	};
   215→
   216→	const handleDragOver = (_event: DragOverEvent) => {
   217→		// Just update visual state if needed, don't create questions
   218→		// Question creation happens in handleDragEnd
   219→	};
   220→
   221→	const handleDragEnd = (event: DragEndEvent) => {
   222→		const { active, over } = event;
   223→		setActiveDragItem(null);
   224→
   225→		if (!over) return;
   226→
   227→		// Handle palette drop on canvas (create new question)
   228→		if (active.data.current?.questionType && over.id === "canvas") {
   229→			const questionType = active.data.current.questionType as Question["type"];
   230→			createMutation.mutate({
   231→				surveyId: survey.id,
   232→				type: questionType,
   233→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   234→				order: questions.length,
   235→			});
   236→			return;
   237→		}
   238→
   239→		// Handle reordering
   240→		if (active.id !== over.id && over.id !== "canvas") {
   241→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   242→			const newIndex = questions.findIndex((q) => q.id === over.id);
   243→
   244→			if (oldIndex !== -1 && newIndex !== -1) {
   245→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   246→					(q, index) => ({
   247→						...q,
   248→						order: index,
   249→					}),
   250→				);
   251→
   252→				setQuestions(newQuestions);
   253→
   254→				reorderMutation.mutate({
   255→					questions: newQuestions.map((q) => ({
   256→						id: q.id,
   257→						order: q.order,
   258→					})),
   259→				});
   260→			}
   261→		}
   262→	};
   263→
   264→	const contextValue: SurveyBuilderContextValue = {
   265→		survey,
   266→		questions,
   267→		selectedQuestionId,
   268→		setSelectedQuestionId,
   269→		activeTab,
   270→		setActiveTab,
   271→		onQuestionsChange: setQuestions,
   272→		paletteOpen,
   273→		setPaletteOpen,
   274→		propertiesOpen,
   275→		setPropertiesOpen,
   276→	};
   277→
   278→	const safeQuestions = questions || [];
   279→
   280→	// Custom drop animation that fades out smoothly
   281→	const dropAnimation: typeof defaultDropAnimation = {
   282→		...defaultDropAnimation,
   283→		duration: 200,
   284→		keyframes: ({ transform }) => [
   285→			{ opacity: 1, transform: CSS.Transform.toString(transform.initial) },
   286→			{
   287→				opacity: 0,
   288→				transform: CSS.Transform.toString({
   289→					...transform.final,
   290→					scale: 0.9,
   291→				} as any),
   292→			},
   293→		],
   294→	};
   295→
   296→	// Render drag overlay
   297→	const renderDragOverlay = () => {
   298→		if (!activeDragItem) return null;
   299→
   300→		if (activeDragItem.type === "palette") {
   301→			const Icon =
   302→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   303→			return (
   304→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   305→					<CardContent className="flex items-center gap-3 p-4">
   306→						<div className="rounded bg-violet-100 p-1.5">
   307→							<Icon className="h-4 w-4 text-violet-600" />
   308→						</div>
   309→						<span className="font-medium">
   310→							{questionTypeLabels[activeDragItem.questionType] ||
   311→								activeDragItem.questionType}
   312→						</span>
   313→					</CardContent>
   314→				</Card>
   315→			);
   316→		}
   317→
   318→		// Dragging existing question
   319→		const activeQuestion = safeQuestions.find(
   320→			(q) => q.id === activeDragItem.id,
   321→		);
   322→		if (activeQuestion) {
   323→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   324→			return (
   325→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   326→					<CardContent className="flex items-center gap-3 p-4">
   327→						<div className="rounded bg-violet-100 p-1.5">
   328→							<Icon className="h-4 w-4 text-violet-600" />
   329→						</div>
   330→						<span className="font-medium">{activeQuestion.title}</span>
   331→					</CardContent>
   332→				</Card>
   333→			);
   334→		}
   335→
   336→		return null;
   337→	};
