   140→
   141→	// Sync state when initialQuestions changes
   142→	useEffect(() => {
   143→		setQuestions(initialQuestions);
   144→	}, [initialQuestions]);
   145→
   146→	// Create question mutation (for palette drops)
   147→	const createMutation = useMutation(
   148→		orpc.question.create.mutationOptions({
   149→			onSuccess: (newQuestion) => {
