   171→	);
   172→
   173→	// DnD sensors
   174→	const sensors = useSensors(
   175→		useSensor(PointerSensor, {
   176→			activationConstraint: {
   177→				distance: 5,
   178→			},
   179→		}),
   180→		useSensor(KeyboardSensor, {
